INSERT INTO supplier_draft_payload VALUES ('{"projects":[{"sourceTag":"supplier-tutorial:2247503647","project":{"title":"悬浮吹球","description":"拼装手吹气管和托环，吹气让泡沫球升起，比较吹气与停止吹气时小球的位置。","category":"科学","video_url":"https://assets.steamx.cc/kejiao16a/current-supplier/ball/62760ae9c865ecbd0859aa4246161a2d4344fae3c54d941c9a620606fde7f2b0.mp4","image_url":"https://assets.steamx.cc/kejiao16a/current-supplier/ball/6f17ddf4ae4d04cc7eb4e355d20031e512d87b9f96338c1a6a75912988dcef1c.jpg","tags":["幼儿园中班","supplier-tutorial:2247503647"],"problem_statement":"供应商当前教程：https://mp.weixin.qq.com/s?__biz=MzI0NzYyMTk2Nw==&mid=2247503647&idx=1&sn=b5e36208496b642adb4760c6d25128d6；原项目版本保留，不覆盖旧教程。","reflection":"向上的气流对泡沫球产生向上的作用力；吹气时小球可能升起，停止吹气后会落下。球的重量、气流强弱和方向都会影响效果。","recommended_min_age":4,"support_level":"guided","difficulty_stars":1,"author_id":"66020423-0000-0000-0000-000000000000","difficulty":"easy","recommended_max_age":null,"status":"pending","moderation_state":"hidden","classification_status":"unreviewed","classification_source":null,"classification_reviewed_at":null,"classification_reviewed_by":null},"materials":[{"material":"配套手吹气管、托环和泡沫球","sort_order":0},{"material":"保持清洁的个人吹嘴；小零件由成人保管，不入口、不共用吹嘴","sort_order":1}],"steps":[{"title":"拼装气管与托环","description":"对照视频把托环装到气管对应位置，检查连接牢固，出气孔没有被遮挡。","image_url":null,"sort_order":0},{"title":"放好小球","description":"保持托环朝上，将配套泡沫球轻放在托环上。","image_url":null,"sort_order":1},{"title":"吹气观察","description":"从吹嘴平稳吹气，观察小球升起；停下吹气，比较小球的位置。不要吸气或把小球放入口中。","image_url":null,"sort_order":2}],"relations":[{"kit_id":"e9f5b164-86cf-56cb-bced-45d650e569db","status":"candidate","preparation_status":"unknown","kit_revision":2,"evidence":{"basis":"current_supplier_directory_tutorial","reviewedAt":"2026-10-31","directoryItemIds":[1136404],"catalogTitle":"悬浮吹球","sourceTag":"supplier-tutorial:2247503647","sourceArticle":"https://mp.weixin.qq.com/s?__biz=MzI0NzYyMTk2Nw==&mid=2247503647&idx=1&sn=b5e36208496b642adb4760c6d25128d6","sourceVideoSha256":"62760ae9c865ecbd0859aa4246